def _pointer(parts):
    return "".join("/" + str(p).replace("~", "~0").replace("/", "~1") for p in parts)


def merge_patch(before, after):
    """Return a JSON Merge Patch value that transforms before into after."""
    if isinstance(before, dict) and isinstance(after, dict):
        patch = {}
        for key in sorted(before.keys() - after.keys()):
            patch[key] = None
        for key in sorted(after):
            if key not in before:
                patch[key] = after[key]
            else:
                value = merge_patch(before[key], after[key])
                if value is not _NO_CHANGE:
                    patch[key] = value
        return patch if patch else _NO_CHANGE
    if before == after and type(before) is type(after):
        return _NO_CHANGE
    return after


class _NoChange:
    pass


_NO_CHANGE = _NoChange()


def render_merge_patch(before, after):
    """Serialize a merge patch. jd represents equality as an empty object."""
    value = merge_patch(before, after)
